<?php require_once __DIR__.'/../config/auth.php';require_admin();$m=[];$m['livros']=db()->query('SELECT COALESCE(SUM(quantidade),0) FROM livros')->fetchColumn();$m['disponiveis']=db()->query('SELECT COALESCE(SUM(quantidade_disponivel),0) FROM livros')->fetchColumn();$m['alunos']=db()->query("SELECT COUNT(*) FROM usuarios WHERE tipo='aluno'")->fetchColumn();$m['ativos']=db()->query("SELECT COUNT(*) FROM emprestimos WHERE status='ativo'")->fetchColumn();$m['atrasados']=db()->query("SELECT COUNT(*) FROM emprestimos WHERE status='ativo' AND data_prevista_devolucao<CURDATE()")->fetchColumn();$m['devolvidos']=db()->query("SELECT COUNT(*) FROM emprestimos WHERE status='devolvido'")->fetchColumn();$late=db()->query("SELECT e.*,u.nome,l.titulo FROM emprestimos e JOIN usuarios u ON u.id=e.usuario_id JOIN livros l ON l.id=e.livro_id WHERE e.status='ativo' AND e.data_prevista_devolucao<CURDATE() ORDER BY e.data_prevista_devolucao LIMIT 5")->fetchAll();$pageTitle='Visão geral';require __DIR__.'/../includes/header.php';require __DIR__.'/../includes/dashboard-nav.php';?><div class="dashboard-cards"><?php foreach(['livros'=>'Total de livros','disponiveis'=>'Livros disponíveis','alunos'=>'Total de alunos','ativos'=>'Empréstimos ativos','atrasados'=>'Empréstimos atrasados','devolvidos'=>'Livros devolvidos'] as $k=>$label):?><div class="card metric"><span><?=e($label)?></span><b><?=number_format((int)$m[$k],0,',','.')?></b></div><?php endforeach;?></div><section class="panel"><h2>Empréstimos atrasados</h2><div class="table-wrap"><table><thead><tr><th>Aluno</th><th>Livro</th><th>Vencimento</th></tr></thead><tbody><?php foreach($late as $l):?><tr><td><?=e($l['nome'])?></td><td><?=e($l['titulo'])?></td><td><span class="badge off"><?=date('d/m/Y',strtotime($l['data_prevista_devolucao']))?></span></td></tr><?php endforeach;?><?php if(!$late):?><tr><td colspan="3" class="empty">Nenhuma pendência no momento.</td></tr><?php endif;?></tbody></table></div></section><?php require __DIR__.'/../includes/dashboard-footer.php';?>
